import { defineExperience, startExperience } from '@signal-lab/experience-sdk';
import { createScene, type PrintScene } from './scene';
import { directScene } from './director';

let scene: PrintScene | null = null;
let root: HTMLElement | null = null;

function buildPage(container: HTMLElement): HTMLElement {
  const page = document.createElement('main');
  page.className = 'print-page';
  page.innerHTML = `
    <style>
      .webgl-ready .paper-fallback { display: none !important; }
      .print-page.is-reduced-motion { min-height: 100svh; }
      .print-page.is-reduced-motion .process,
      .print-page.is-reduced-motion .booking,
      .print-page.is-reduced-motion .canvas-note,
      .print-page.is-reduced-motion .text-link { display: none; }
      .print-page.is-reduced-motion .print-hero { min-height: 100svh; }
      .print-page.is-reduced-motion .hero-cta { display: inline-block; margin-top: 8px; }
      .print-page.is-reduced-motion .hero-copy { position: relative; z-index: 3; }
      .booking {
        background: linear-gradient(90deg, rgba(242,220,177,.84), rgba(242,220,177,.18) 34%, transparent 48%, rgba(242,220,177,.12) 66%, rgba(242,220,177,.8));
      }
      .process article { max-width: 290px; }
      .process h2 { font-size: clamp(21px, 2.25vw, 31px); }
      .process {
        grid-template-columns: minmax(0, 1fr) minmax(280px, 360px);
        gap: 14px;
        align-content: center;
      }
      .process article,
      .process article:nth-child(2),
      .process article:nth-child(3) {
        grid-column: 2;
        margin: 0;
        max-width: none;
        padding: 14px 18px 16px;
        background: rgba(239, 211, 162, .82);
        border-top-color: rgba(45, 39, 31, .35);
        box-shadow: 0 18px 42px rgba(91, 52, 25, .08);
      }
      .booking {
        align-items: end;
        padding-top: 58vh;
        background: linear-gradient(180deg, transparent 0 46%, rgba(242,220,177,.5) 68%, rgba(242,220,177,.92));
      }
      @media (max-width: 700px) {
        .process { display: flex; gap: 12vh; }
        .process article,
        .process article:nth-child(2),
        .process article:nth-child(3) { max-width: 78%; }
        .process article:nth-child(2) { margin-left: auto; }
        .booking { padding-top: 16vh; }
      }
    </style>
    <nav class="print-nav" aria-label="页面导航">
      <a class="print-mark" href="#opening">日光套印所</a>
      <a href="#booking">预约体验</a>
    </nav>
    <div class="paper-fallback" aria-hidden="true">
      <img src="/creative-assets/r31-woodblock/washi-final-print-v1.png" alt="" style="display:block;width:100%;height:auto">
    </div>
    <section class="print-hero" id="opening" aria-labelledby="hero-title">
      <div class="hero-copy">
        <p class="eyebrow">一张和纸 · 三次落版</p>
        <h1 id="hero-title">让纸记住<br>手的力度</h1>
        <p class="hero-lede">在日光与木香之间，亲手完成靛蓝海浪与朱红飞鸟的套印。</p>
        <a class="text-link" href="#process">沿着纸面看套色 <span aria-hidden="true">↓</span></a>
        <a class="hero-cta" href="#booking">预约一次亲手套印 <span aria-hidden="true">↗</span></a>
      </div>
      <p class="canvas-note">滚动，观察同一张纸逐层成形</p>
    </section>
    <section class="process" id="process" aria-label="木版套印过程">
      <article><span>01</span><h2>木纹先留下压力</h2><p>湿润的和纸贴合刻版，纤维顺着刀痕轻轻下陷。</p></article>
      <article><span>02</span><h2>靛蓝压出海浪</h2><p>墨色被纸纤维吸收，深浅来自一次真实的手工施压。</p></article>
      <article><span>03</span><h2>朱红允许一点错位</h2><p>飞鸟略偏离刻线，那一点不齐，正是每张作品的签名。</p></article>
    </section>
    <section class="booking" id="booking" aria-labelledby="booking-title">
      <div>
        <p class="eyebrow">两小时 · 小班制 · 材料齐备</p>
        <h2 id="booking-title">带走一张<br>只属于你的浪</h2>
      </div>
      <div class="booking-action">
        <p>从润纸、上墨到对版，工匠会陪你完成每一道工序。无需绘画经验。</p>
        <a class="cta" href="mailto:studio@example.com?subject=预约一次亲手套印">预约一次亲手套印 <span aria-hidden="true">↗</span></a>
      </div>
    </section>`;
  container.appendChild(page);
  return page;
}

startExperience(defineExperience({
  mount(context) {
    root = buildPage(context.container);
    root.classList.toggle('is-reduced-motion', context.reducedMotion);
    try {
      scene = createScene(context.canvas, context.viewport.width, context.viewport.height, context.viewport.dpr, context.quality === 'low');
      root.classList.add('webgl-ready');
    } catch {
      context.canvas.style.display = 'none';
      scene = null;
      root.classList.add('webgl-fallback');
    }
  },
  update(frame) {
    if (!scene) return;
    directScene(scene, frame.reducedMotion ? 1 : frame.progress, frame.pointer.x, frame.pointer.y, frame.elapsed, frame.reducedMotion);
    scene.renderer.render(scene.world, scene.camera);
  },
  resize(viewport) {
    if (scene) scene.resize(viewport.width, viewport.height, viewport.dpr);
  },
  dispose() {
    scene?.dispose();
    scene = null;
    root?.remove();
    root = null;
  }
}));

import * as THREE from 'three';

export interface PrintScene {
  renderer: THREE.WebGLRenderer;
  world: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  paper: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>;
  paperMaterial: THREE.ShaderMaterial;
  presses: THREE.Mesh<THREE.BoxGeometry, THREE.MeshStandardMaterial>[];
  shadow: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
  resize(width: number, height: number, dpr: number): void;
  dispose(): void;
}

const vertexShader = `
  varying vec2 vUv;
  varying float vRelief;
  uniform float uRelief;
  uniform float uTime;
  float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
  void main(){
    vUv=uv;
    float fiber=(hash(floor(uv*vec2(90.0,58.0)))-.5)*.008;
    float wave=sin(uv.x*24.0+sin(uv.y*13.0))*uRelief*.012;
    vRelief=wave+fiber;
    vec3 p=position;
    p.z+=vRelief+sin(uv.x*3.14159)*sin(uv.y*3.14159)*.025;
    gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.0);
  }`;

const fragmentShader = `
  precision highp float;
  varying vec2 vUv;
  varying float vRelief;
  uniform sampler2D uArtwork;
  uniform float uIndigo;
  uniform float uVermilion;
  uniform float uRelief;
  uniform float uTime;
  uniform vec2 uPointer;
  float hash(vec2 p){ return fract(sin(dot(p,vec2(41.3,289.1)))*45758.5453); }
  void main(){
    vec2 uv=vUv;
    float grain=hash(floor(uv*vec2(260.0,170.0)))*.06;
    float longFiber=sin(uv.x*430.0+sin(uv.y*31.0))*sin(uv.y*260.0)*.018;
    vec3 paper=vec3(.965,.925,.82)+grain+longFiber;
    float deckle=smoothstep(.0,.025,min(min(uv.x,1.0-uv.x),min(uv.y,1.0-uv.y)));
    vec4 artwork=texture2D(uArtwork,uv);
    float artAlpha=smoothstep(.42,.86,artwork.a);
    float high=max(max(artwork.r,artwork.g),artwork.b);
    float low=min(min(artwork.r,artwork.g),artwork.b);
    float luminance=dot(artwork.rgb,vec3(.2126,.7152,.0722));
    float chromaInk=smoothstep(.025,.12,high-low);
    float darkInk=1.0-smoothstep(.48,.82,luminance);
    float inkMask=max(chromaInk,darkInk)*artAlpha;
    float redClass=smoothstep(.015,.11,artwork.r-artwork.b);
    float redMask=inkMask*redClass;
    float blueMask=inkMask*(1.0-redClass);
    float neutralMask=clamp(artAlpha-inkMask,0.0,1.0);
    vec3 color=mix(paper,artwork.rgb,neutralMask*.9);
    float blueSweep=(1.0-smoothstep(uIndigo*1.2-.14,uIndigo*1.2+.14,uv.x))*uIndigo;
    float redSweep=smoothstep(1.12-uVermilion*1.28,1.32-uVermilion*1.28,uv.x)*uVermilion;
    color=mix(color,artwork.rgb,clamp(blueMask*blueSweep+redMask*redSweep,0.0,1.0));
    float sheen=max(0.0,1.0-distance(uv,uPointer*.12+vec2(.5))*.9)*.025;
    color+=sheen+uRelief*vRelief*1.3;
    float printState=max(uIndigo,uVermilion);
    gl_FragColor=vec4(color,mix(deckle,artAlpha,printState));
  }`;

function createWoodTexture(): THREE.CanvasTexture {
  const canvas=document.createElement('canvas');
  canvas.width=512;
  canvas.height=512;
  const context=canvas.getContext('2d');
  if(!context) return new THREE.CanvasTexture(canvas);
  const gradient=context.createLinearGradient(0,0,512,512);
  gradient.addColorStop(0,'#b8753e');
  gradient.addColorStop(.48,'#d49a5e');
  gradient.addColorStop(1,'#a96537');
  context.fillStyle=gradient;
  context.fillRect(0,0,512,512);
  for(let index=0;index<42;index+=1){
    const y=index*13+Math.sin(index*1.7)*7;
    context.beginPath();
    context.moveTo(0,y);
    for(let x=0;x<=512;x+=24) context.lineTo(x,y+Math.sin(x*.035+index)*4);
    context.strokeStyle=index%5===0?'rgba(88,43,20,.16)':'rgba(255,231,184,.09)';
    context.lineWidth=index%5===0?2:1;
    context.stroke();
  }
  const texture=new THREE.CanvasTexture(canvas);
  texture.colorSpace=THREE.SRGBColorSpace;
  texture.wrapS=texture.wrapT=THREE.RepeatWrapping;
  texture.repeat.set(2.6,1.8);
  return texture;
}

export function createScene(canvas: HTMLCanvasElement, width: number, height: number, dpr: number, lowQuality: boolean): PrintScene {
  const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: !lowQuality, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(dpr, lowQuality ? 1.25 : 2));
  renderer.setSize(width, height, false);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.shadowMap.enabled = !lowQuality;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;

  const world = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(35, width / Math.max(height, 1), .1, 30);
  camera.position.set(0, 3.8, 4.4);
  camera.lookAt(0, 0, 0);

  const tableTexture=createWoodTexture();
  tableTexture.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());
  const tableMaterial = new THREE.MeshStandardMaterial({ color: 0xc58a52, map: tableTexture, roughness: .82, metalness: 0 });
  const table = new THREE.Mesh(new THREE.PlaneGeometry(20, 14), tableMaterial);
  table.rotation.x = -Math.PI / 2;
  table.position.y = -.14;
  world.add(table);

  const artwork=new THREE.TextureLoader().load('/creative-assets/r31-woodblock/washi-final-print-v1.png');
  artwork.colorSpace=THREE.SRGBColorSpace;
  artwork.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());
  const paperMaterial = new THREE.ShaderMaterial({
    vertexShader, fragmentShader, transparent: true, side: THREE.DoubleSide,
    uniforms: {
      uArtwork: { value: artwork }, uIndigo: { value: 0 }, uVermilion: { value: 0 }, uRelief: { value: 0 },
      uTime: { value: 0 }, uPointer: { value: new THREE.Vector2() }
    }
  });
  const paper = new THREE.Mesh(new THREE.PlaneGeometry(3.55, 2.36, lowQuality ? 32 : 72, lowQuality ? 22 : 48), paperMaterial);
  paper.rotation.x = -Math.PI / 2;
  paper.position.y = .18;
  paper.castShadow = !lowQuality;
  world.add(paper);

  const shadowMaterial = new THREE.MeshBasicMaterial({ color: 0x56351f, transparent: true, opacity: .16, depthWrite: false });
  const shadow = new THREE.Mesh(new THREE.PlaneGeometry(3.7, 2.5), shadowMaterial);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -.125;
  world.add(shadow);

  const pressGeometry = new THREE.BoxGeometry(3.35, .09, 2.16);
  const pressColors = [0x9b6339, 0x315979, 0xa84532];
  const presses = pressColors.map((color, index) => {
    const material = new THREE.MeshStandardMaterial({ color, roughness: .86, transparent: true, opacity: 0 });
    const mesh = new THREE.Mesh(pressGeometry, material);
    mesh.position.set(0, 2.6 + index * .18, 0);
    mesh.castShadow = !lowQuality;
    world.add(mesh);
    return mesh;
  });

  world.add(new THREE.HemisphereLight(0xfff5db, 0x8b5735, 2.1));
  const sun = new THREE.DirectionalLight(0xffe3b0, 3.2);
  sun.position.set(-3, 6, 4);
  sun.castShadow = !lowQuality;
  world.add(sun);

  const resize = (nextWidth: number, nextHeight: number, nextDpr: number): void => {
    camera.aspect = nextWidth / Math.max(nextHeight, 1);
    camera.updateProjectionMatrix();
    renderer.setPixelRatio(Math.min(nextDpr, lowQuality ? 1.25 : 2));
    renderer.setSize(nextWidth, nextHeight, false);
  };
  const dispose = (): void => {
    paper.geometry.dispose();
    paperMaterial.dispose();
    shadow.geometry.dispose();
    shadowMaterial.dispose();
    pressGeometry.dispose();
    for (const press of presses) press.material.dispose();
    table.geometry.dispose();
    tableMaterial.dispose();
    tableTexture.dispose();
    artwork.dispose();
    renderer.dispose();
  };
  return { renderer, world, camera, paper, paperMaterial, presses, shadow, resize, dispose };
}

import * as THREE from 'three';
import type { PrintScene } from './scene';

const target = new THREE.Vector3();
const ease = (value: number): number => {
  const x = THREE.MathUtils.clamp(value, 0, 1);
  return x * x * (3 - 2 * x);
};
const windowPulse = (progress: number, center: number, width: number): number =>
  Math.max(0, 1 - Math.abs(progress - center) / width);

export function directScene(scene: PrintScene, progress: number, pointerX: number, pointerY: number, elapsed: number, reducedMotion: boolean): void {
  const p = THREE.MathUtils.clamp(progress, 0, 1);
  const relief = ease((p - .08) / .2);
  const indigo = ease((p - .27) / .23);
  const vermilion = ease((p - .59) / .22);
  scene.paperMaterial.uniforms.uRelief.value = relief;
  scene.paperMaterial.uniforms.uIndigo.value = indigo;
  scene.paperMaterial.uniforms.uVermilion.value = vermilion;
  scene.paperMaterial.uniforms.uTime.value = elapsed;
  scene.paperMaterial.uniforms.uPointer.value.set(pointerX, pointerY);

  const centers = [.18, .43, .69];
  for (let index = 0; index < scene.presses.length; index += 1) {
    const press = scene.presses[index];
    const pulse = windowPulse(p, centers[index], .115);
    press.position.y = .28 + (1 - ease(pulse)) * 2.2;
    press.material.opacity = pulse * .42;
    press.visible = pulse > .015 && !reducedMotion;
  }

  const settle = ease((p - .78) / .18);
  const processFocus = windowPulse(p, .5, .34);
  scene.paper.position.x = -.58 * processFocus;
  scene.paper.position.y = .18 - settle * .045;
  scene.paper.rotation.z = THREE.MathUtils.lerp(-.025, .012, settle);
  scene.shadow.material.opacity = .13 + settle * .1;
  scene.shadow.position.x = scene.paper.position.x;
  for (const press of scene.presses) press.position.x = scene.paper.position.x;

  const side = reducedMotion ? 0 : pointerX * .055;
  scene.camera.position.x = THREE.MathUtils.lerp(-.42, .18, ease(p)) + side;
  scene.camera.position.y = THREE.MathUtils.lerp(3.65, 4.05, settle);
  scene.camera.position.z = THREE.MathUtils.lerp(4.55, 4.05, settle) + pointerY * .03;
  target.set(THREE.MathUtils.lerp(.25, 0, settle), 0, 0);
  scene.camera.lookAt(target);
}
